(function(){
  var root=document.documentElement;
  try{var t=localStorage.getItem('theme');if(t)root.setAttribute('data-theme',t)}catch(e){}
  var SUN='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="4.2"/><path d="M12 2.5v2.2M12 19.3v2.2M2.5 12h2.2M19.3 12h2.2M5.3 5.3l1.6 1.6M17.1 17.1l1.6 1.6M18.7 5.3l-1.6 1.6M6.9 17.1l-1.6 1.6"/></svg>',MOON='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.5 14.2A8.5 8.5 0 0 1 9.8 3.5a8.5 8.5 0 1 0 10.7 10.7z"/></svg>';
  function isDark(){var c=root.getAttribute('data-theme');return c?c==='dark':matchMedia('(prefers-color-scheme: dark)').matches}
  function paintTheme(){var b=document.getElementById('theme'),d=isDark();b.innerHTML=d?SUN:MOON;var l=d?'Switch to light mode':'Switch to dark mode';b.setAttribute('aria-label',l);b.title=l}
  paintTheme();
  document.getElementById('theme').addEventListener('click',function(){
    var cur=root.getAttribute('data-theme');
    var dark=cur?cur==='dark':matchMedia('(prefers-color-scheme: dark)').matches;
    var next=dark?'light':'dark';root.setAttribute('data-theme',next);
    try{localStorage.setItem('theme',next)}catch(e){}
    paintTheme();
  });
  // projects slider: 2 projects per slide, arrows to flip
  var pS=document.getElementById('pslider'),pSl=pS?[].slice.call(pS.querySelectorAll('.pslide')):[],pI=0;
  function setSlide(n){
    if(!pS)return;pI=Math.max(0,Math.min(pSl.length-1,n));
    pSl.forEach(function(el,i){el.hidden=(i!==pI)});
    pS.querySelector('.prev').disabled=(pI===0);pS.querySelector('.next').disabled=(pI===pSl.length-1);
    pS.querySelector('.pcount').textContent=(pI+1)+' / '+pSl.length;
  }
  if(pS){
    pS.querySelector('.prev').addEventListener('click',function(){setSlide(pI-1)});
    pS.querySelector('.next').addEventListener('click',function(){setSlide(pI+1)});
    document.addEventListener('keydown',function(e){
      var pg=document.querySelector('[data-page="projects"]');if(!pg||pg.hidden)return;
      var tg=e.target&&e.target.tagName;if(tg==='INPUT'||tg==='TEXTAREA')return;
      if(e.key==='ArrowRight')setSlide(pI+1);else if(e.key==='ArrowLeft')setSlide(pI-1);
    });
    setSlide(0);
  }
  // page router (hash based)
  var pages=['home','about','skills','experience','projects','feats','resume','sih','paypal','more','contact'];
  var els={};pages.forEach(function(n){els[n]=document.querySelector('[data-page="'+n+'"]')});
  var cur=null;
  function go(name,first){
    if(pages.indexOf(name)<0)name=cur||'home';
    if(name===cur&&!first)return;
    pages.forEach(function(n){if(els[n])els[n].hidden=(n!==name)});
    document.querySelectorAll('nav a.l').forEach(function(a){
      if(a.getAttribute('href')==='#'+(name==='sih'||name==='more'||name==='paypal'?'feats':name))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');
    });
    cur=name;
    if(!first){window.scrollTo(0,0);try{els[name].focus({preventScroll:true})}catch(e){}}
  }
  function show(first){go((location.hash||'').replace('#',''),first)}
  // click-based routing: works even where the URL hash can't change (previews, iframes, file viewers)
  document.addEventListener('click',function(e){
    var a=e.target.closest&&e.target.closest('a[href^="#"]');
    if(!a)return;
    var name=a.getAttribute('href').slice(1);
    if(pages.indexOf(name)<0)return;
    e.preventDefault();
    go(name,false);
    // optional: jump to a specific block on the target page (e.g. data-focus="terramind")
    var f=a.getAttribute('data-focus'),t=f&&document.getElementById(f);
    if(t){var sl=t.closest&&t.closest('.pslide');if(sl)setSlide(+sl.getAttribute('data-i'))}
    if(t){setTimeout(function(){t.scrollIntoView({behavior:'smooth',block:'start'});t.classList.remove('flash');void t.offsetWidth;t.classList.add('flash')},60)}
    try{history.replaceState(null,'','#'+name)}catch(err){try{location.hash=name}catch(e2){}}
  });
  addEventListener('hashchange',function(){show(false)});
  show(true);
  // code symbols cycle inside the PORTFOLIO word
  (function(){
    var m=document.querySelector('.mono');
    var data=["", "", "", "", ""];
    var names=['Java','Python','JavaScript','HTML','CSS'];
    if(!m)return;
    m.classList.add('code');m.innerHTML='';
    var im=data.map(function(d,i){var e=new Image();e.src='data:image/png;base64,'+d;e.alt=names[i];e.decoding='async';if(!i)e.className='on';m.appendChild(e);return e});
    if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
    var k=0;setInterval(function(){im[k].className='';k=(k+1)%im.length;im[k].className='on'},1500);
  })();
  // keep the big hero word on one line and inside the screen, whatever font width loads
  function fitWord(){var w=document.querySelector('.hero .word');if(!w||!w.offsetParent)return;
    w.style.whiteSpace='nowrap';w.style.fontSize='';
    var fs=parseFloat(getComputedStyle(w).fontSize),avail=w.clientWidth*0.97,need=w.scrollWidth;
    if(need>avail){w.style.fontSize=(fs*avail/need).toFixed(1)+'px'}}
  fitWord();addEventListener('load',fitWord);addEventListener('resize',fitWord);addEventListener('hashchange',function(){setTimeout(fitWord,60)});
  if(document.fonts&&document.fonts.ready)document.fonts.ready.then(fitWord);
  // torn paper edges
  function edge(n,fn){var a=[];for(var i=0;i<=n;i++)a.push(fn(i/n));return a}
  document.querySelectorAll('[data-tear]').forEach(function(el){
    var w=el.getAttribute('data-tear').split(',');var n=70;
    var top=w.indexOf('top')>-1,bot=w.indexOf('bottom')>-1;
    function jag(){return (4+Math.random()*13).toFixed(1)}
    var pts=edge(n,function(f){return (f*100).toFixed(2)+'% '+(top?jag():0)+'px'});
    var b=edge(n,function(f){return (f*100).toFixed(2)+'% calc(100% - '+(bot?jag():0)+'px)'}).reverse();
    el.style.setProperty('--tear','polygon('+pts.concat(b).join(',')+')');
  });
  // marquees: duplicate content for a seamless loop
  document.querySelectorAll('[data-dup]').forEach(function(tr){tr.innerHTML+=tr.innerHTML});
})();
